import{_ as o,o as r,c as e,ag as a}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"马兆远访谈核实：AI 时代的内卷、教育与\\"月球工业伴星\\"","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/career-observation/ma-zhaoyuan-interview-ai-involution.md","filePath":"topics/career-observation/ma-zhaoyuan-interview-ai-involution.md"}'),d={name:"topics/career-observation/ma-zhaoyuan-interview-ai-involution.md"};function n(s,t,i,l,g,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="马兆远访谈核实-ai-时代的内卷、教育与-月球工业伴星" tabindex="-1">马兆远访谈核实：AI 时代的内卷、教育与&quot;月球工业伴星&quot; <a class="header-anchor" href="#马兆远访谈核实-ai-时代的内卷、教育与-月球工业伴星" aria-label="Permalink to &quot;马兆远访谈核实：AI 时代的内卷、教育与&quot;月球工业伴星&quot;&quot;">​</a></h1><blockquote><p>关键词：马兆远、南方科技大学、王钦文、内卷、赛道思维、花园思维、心流、师徒制、小班制、社会安全感、出生率、罗素、闲散颂、将错就错、不确定性、体育、动手能力、AI Native、月球工业伴星、归属核实、时间错位</p></blockquote><p><strong>核实对象</strong>：2026-10-24 用户转来 <strong>王钦文 对话 南方科技大学教授 马兆远</strong> 的访谈摘要（九个段落） <strong>核实结论</strong>：<strong>人物身份完全属实</strong>（且履历比视频里说的更强）；<strong>观点类内容无&quot;真伪&quot;可言，只需核对归属</strong>；<strong>唯一的技术性构想（月球工业伴星）存在显著时间错位</strong> —— 详见 <a href="/zhishiku-reading/topics/space-energy/lunar-industrial-satellite.html"><code>../space-energy/lunar-industrial-satellite.md</code></a>。</p><blockquote><p>⚠️ 我只拿到<strong>文字摘要</strong>，不是视频本身。因此&quot;他究竟怎么说&quot;无法独立核实；本篇核实的是<strong>可核查的归属与事实</strong>。</p></blockquote><hr><h2 id="一、人物卡-已由南方科技大学官网核实" tabindex="-1">一、人物卡（已由南方科技大学官网核实） <a class="header-anchor" href="#一、人物卡-已由南方科技大学官网核实" aria-label="Permalink to &quot;一、人物卡（已由南方科技大学官网核实）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>内容</th><th>来源</th></tr></thead><tbody><tr><td>现职</td><td><strong>南方科技大学 自动化与智能制造学院 长聘教授</strong>（2022–至今）；商学院兼职教授</td><td>SUSTech 官网师资页</td></tr><tr><td>出生</td><td><strong>1979 年</strong>生于山西太原</td><td>百度百科</td></tr><tr><td>学历</td><td>2001 北京大学（原子核物理及核技术）学士 → <strong>2005 牛津大学（原子与激光物理）博士</strong></td><td>SUSTech 官网</td></tr><tr><td>博士后</td><td>2006–2007 美国 NIST / 马里兰大学联合量子研究所（JQI）；2007–2009 <strong>加州大学伯克利分校</strong>物理系</td><td>SUSTech 官网</td></tr><tr><td>中科院</td><td>2009–2015 中国科学院上海光学精密机械研究所研究员；2009 获聘中科院研究员、博士生导师</td><td>SUSTech 官网</td></tr><tr><td>★ 硬成果</td><td><strong>为天宫四号设计了世界上第一个宇航空间站超冷原子实验平台</strong></td><td>SUSTech 官网</td></tr><tr><td>其他</td><td>2017–2020 英国谢菲尔德大学智能制造专业教授；2018–2022 清华大学未来实验室首席研究员 / 数字化先进制造研究中心主任；2020–2021 清华深圳国际研究生院院长助理</td><td>SUSTech 官网</td></tr><tr><td>头衔</td><td><strong>英国物理学会会士（FInstP）</strong></td><td>SUSTech 官网</td></tr><tr><td>著作</td><td>《量子大唠嗑》（中信，2016）、《人工智能之不能》<em>AI-Not</em>（中信，2020）、《智造中国》</td><td>SUSTech 官网</td></tr></tbody></table><p><strong>判定</strong>：视频称其&quot;南方科技大学教授&quot; ✅ <strong>属实</strong>（更准确是&quot;自动化与智能制造学院长聘教授&quot;）。</p><p>⚠️ 两处记录在案的不一致：</p><ol><li><strong>牛津博士年份</strong>：SUSTech <strong>中文页记 2005</strong>，<strong>英文页记 2004</strong>（D.Phil.）—— 校方自相矛盾，差 1 年，不影响身份判定</li><li><strong>&quot;俄罗斯工程院外籍院士&quot;</strong>（仅见于百度百科）：该机构与俄罗斯科学院（RAS，国家科学院体系）<strong>并非同一体系</strong>。本项<strong>未做独立核实</strong>，标为待核 —— 这正是&quot;程度夸大/主体错位&quot;检查清单要拦下的那类头衔</li></ol><hr><h2 id="二、九个段落逐段处理" tabindex="-1">二、九个段落逐段处理 <a class="header-anchor" href="#二、九个段落逐段处理" aria-label="Permalink to &quot;二、九个段落逐段处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段落</th><th>内容</th><th>处理</th></tr></thead><tbody><tr><td>1</td><td>AI 让人<strong>更自由还是更内卷</strong></td><td>观点（提问式，非断言）</td></tr><tr><td>2</td><td>技术进步取代旧工作，但人类创造力会<strong>迭代出新职业</strong></td><td>⚠️ <strong>有争议的经济学命题</strong>（&quot;补偿理论&quot;）。技术性失业 vs 新职业创造在实证上高度分化，不宜当公理。★ 与本库实测数据对照：METR 随机对照试验显示资深开发者在熟悉项目上用 AI <strong>反而慢 19%</strong>（见 <code>ai-leverage-playbook.md</code>）</td></tr><tr><td>2</td><td>结合<strong>罗素关于技术进步与人类幸福的百年前思考</strong></td><td>✅ <strong>方向属实</strong>，出处基本可定：《闲散颂》系列（单行本 1935）→ 见 <span class="uncollected-link" title="此关联资料尚未收录到阅读站"><code>../philosophy/russell-in-praise-of-idleness.md</code></span>。⚠️ 但<strong>罗素的原意被偏移了</strong>（他要的是<strong>分配</strong>，不是技术乐观论）；&quot;百年前&quot;是约数（实际约 90 年）</td></tr><tr><td>2</td><td>过度竞争<strong>扼杀创造力</strong>、影响<strong>人口出生率</strong>；物质丰富后<strong>发展放缓是必然</strong></td><td>观点（可讨论）</td></tr><tr><td>3</td><td>内卷根源 = <strong>缺乏社会提供的安全感</strong>，主要体现为<strong>住房、教育、医疗</strong>三大</td><td>观点，但<strong>可验证的结构性事实</strong>：三大民生支出确实是东亚低生育率研究里的核心变量</td></tr><tr><td>3</td><td>未来教育可能回归<strong>小班制 / 师徒制</strong></td><td>观点（与&quot;可操作&quot;距离远，属方向性判断）</td></tr><tr><td>4</td><td>摒弃工业时代**&quot;赛道思维&quot;<strong>，拥抱</strong>&quot;花园思维&quot;**</td><td>✅ <strong>观点类，但表述已成型、可操作</strong>：每个人有自己的轨迹和花期。★ 与 <code>finding-life-direction.md</code>、<code>self-motivation.md</code> 呼应</td></tr><tr><td>5</td><td>人才选拔看<strong>体育</strong>（抗打击能力）与<strong>动手能力</strong>（解决实际问题 + 高度专注获得<strong>平静与心流</strong>）</td><td>观点。★ &quot;动手→心流&quot;这一条有真实的心理学支撑（心流条件：明确目标+即时反馈+技能与挑战匹配）</td></tr><tr><td>6</td><td>身边跨学科、跨年龄的多元人生；<strong>不必因害怕选错而焦虑</strong>；<strong>&quot;将错就错&quot;</strong></td><td>观点（反规划取向）</td></tr><tr><td>7</td><td><strong>将月球打造为地球的工业伴星</strong>，铺太阳能电站、能量传回地球，彻底解决能源需求</td><td>❌ <strong>时间错位</strong>：该构想有 <strong>1979-04-30 NASA 报告</strong> 的量化论证（30 座 × 10 GW），非新构想；且<strong>当前工程路线是 GEO 而非月球</strong>。详见 <a href="/zhishiku-reading/topics/space-energy/lunar-industrial-satellite.html"><code>../space-energy/lunar-industrial-satellite.md</code></a></td></tr></tbody></table><p><strong>核实方法结论</strong>：<strong>这一篇的失真相貌与前几篇完全不同。</strong> 它不是&quot;标题党打假&quot;式的问题 —— 人物真实、引用有据、观点自洽。它唯一的硬伤在<strong>最后那段&quot;宏大构想&quot;的时间坐标</strong>：把一个有近半个世纪历史的方案放在了&quot;视频最后提出的展望&quot;这个位置上。</p><p>★ 这提示一条新的判据：<strong>访谈类内容的失真高发区不在观点，而在&quot;时间坐标&quot;和&quot;归属坐标&quot;。</strong> 观点无法证伪，但&quot;这是谁在什么时候提出的&quot;可以。</p><hr><h2 id="三、三个可以直接用的思维工具" tabindex="-1">三、三个可以直接用的思维工具 <a class="header-anchor" href="#三、三个可以直接用的思维工具" aria-label="Permalink to &quot;三、三个可以直接用的思维工具&quot;">​</a></h2><h3 id="_1-花园思维-gardening-替代赛道思维-track" tabindex="-1">1. 花园思维（Gardening）替代赛道思维（Track） <a class="header-anchor" href="#_1-花园思维-gardening-替代赛道思维-track" aria-label="Permalink to &quot;1. 花园思维（Gardening）替代赛道思维（Track）&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>赛道思维</th><th>花园思维</th></tr></thead><tbody><tr><td>隐喻</td><td>同一条跑道上比先后</td><td>各有各的土壤与花期</td></tr><tr><td>目标</td><td>超过别人</td><td>把想做的事做到极致</td></tr><tr><td>面对更迭</td><td>怕赛道被换掉</td><td>换土继续长</td></tr><tr><td>与 AI 的关系</td><td>怕被更强的选手超过</td><td>做 AI 不能替的那部分</td></tr></tbody></table><p>★ <strong>&quot;将想做的事发挥到极致，才是抗衡 AI 时代的关键&quot;</strong> —— 这与本库 <code>reverse-ability-ai-era.md</code> 的&quot;找 AI 替代不了的需求&quot;是同一主张的两种说法。</p><h3 id="_2-体育-动手能力-作为-抗打击-和-心流-的入口" tabindex="-1">2. 体育 + 动手能力：作为&quot;抗打击&quot;和&quot;心流&quot;的入口 <a class="header-anchor" href="#_2-体育-动手能力-作为-抗打击-和-心流-的入口" aria-label="Permalink to &quot;2. 体育 + 动手能力：作为&quot;抗打击&quot;和&quot;心流&quot;的入口&quot;">​</a></h3><ul><li><strong>体育 → 抗打击能力</strong>：反复失败的耐受性训练</li><li><strong>动手 → 心流</strong>：明确目标（做出东西）+ 即时反馈（好不好用立刻知道）+ 技能与挑战匹配 ★ 这解释了为什么&quot;动手&quot;在 AI 时代反而升值：<strong>它不是在生产物件，它在生产专注状态。</strong></li></ul><h3 id="_3-将错就错-接受不确定性" tabindex="-1">3. 将错就错：接受不确定性 <a class="header-anchor" href="#_3-将错就错-接受不确定性" aria-label="Permalink to &quot;3. 将错就错：接受不确定性&quot;">​</a></h3><ul><li>前提：<strong>在一个富足的社会里</strong>，选错的代价下降了</li><li>阻力：惯性思维 + <strong>算法推送造成的压力</strong>（看到别人都在某条路上）</li><li>处方：不追求一次选对，追求<strong>迭代修正</strong></li></ul><hr><h2 id="四、跨主题连接" tabindex="-1">四、跨主题连接 <a class="header-anchor" href="#四、跨主题连接" aria-label="Permalink to &quot;四、跨主题连接&quot;">​</a></h2><ul><li>★ <a href="/zhishiku-reading/topics/space-energy/lunar-industrial-satellite.html"><code>../space-energy/lunar-industrial-satellite.md</code></a> —— 月球工业伴星构想的完整核实</li><li>★ <span class="uncollected-link" title="此关联资料尚未收录到阅读站"><code>../philosophy/russell-in-praise-of-idleness.md</code></span> —— 罗素《闲散颂》：本篇引用它的出处核实 + 原意偏移</li><li>★ <a href="/zhishiku-reading/topics/philosophy/poverty-busy-trap.html"><code>../philosophy/poverty-busy-trap.md</code></a> —— 穷忙陷阱：内卷的经济结构面</li><li>★ <a href="/zhishiku-reading/topics/philosophy/labor-alienation-marx.html"><code>../philosophy/labor-alienation-marx.md</code></a> + <a href="/zhishiku-reading/topics/philosophy/labor-alienation-mao-perspective.html"><code>labor-alienation-mao-perspective.md</code></a> —— 劳动异化的三种解：马克思（产品不属于劳动者）/ 罗素（劳动之德是特权道德）/ 本篇（缺安全感）</li><li>★ <a href="/zhishiku-reading/topics/career-observation/ai-workplace-paradox.html"><code>ai-workplace-paradox.md</code></a> —— AI 时代职场悖论：效率提升反被裁员、工贼困境 → <strong>与&quot;AI 让人更自由&quot;直接对立的一手观察</strong></li><li>★ <a href="/zhishiku-reading/topics/career-observation/ai-leverage-playbook.html"><code>ai-leverage-playbook.md</code></a> —— METR 实测&quot;资深开发者用 AI 慢 19%&quot;：<strong>对第 2 段&quot;技术进步提升生活丰富度&quot;的最有力的反例</strong></li><li><a href="/zhishiku-reading/topics/career-observation/reverse-ability-ai-era.html"><code>reverse-ability-ai-era.md</code></a> —— 花园思维的工程版</li><li><a href="/zhishiku-reading/topics/psychology/"><code>../psychology/</code></a> —— 心流的条件</li><li><a href="/zhishiku-reading/topics/family-education/"><code>../family-education/</code></a> —— 小班制/师徒制、体育与动手能力</li></ul>',27)])])}const p=o(d,[["render",n]]);export{c as __pageData,p as default};
